 [Fact] public async Task ExpiredOperationFailsExplicitlyInBackgroundAndRetainsPreviousCover(){await using var f=await Fixture.Create();await f.Entities.PatchAsync(f.Campaign.Id,new(){["cover_asset"]="previous.png"});var op=await f.Generation.StartAsync(f.Campaign.Id.ToString(),f.Gm.Id.ToString(),new("image","Idea",1,Guid.NewGuid().ToString()),default);await f.Entities.PatchAsync(op.Id,new(){["deadline"]=DateTimeOffset.UtcNow.AddSeconds(-1).ToUnixTimeSeconds()});await f.Generation.StartAsync(default(CancellationToken));var done=await f.Store.RequireAsync(op.TypeSlug,op.Id.ToString());for(var n=0;n<100&&done.Data.Text("state")!="failed";n++){await Task.Delay(10);done=await f.Store.RequireAsync(op.TypeSlug,op.Id.ToString());}await f.Generation.StopAsync(default);Assert.Equal("failed",done.Data.Text("state"));Assert.NotEmpty(done.Data.Text("error"));Assert.Equal("previous.png",(await f.Store.RequireAsync(f.Campaign.TypeSlug,f.Campaign.Id.ToString())).Data.Text("cover_asset"));Assert.Empty(f.Compute.ImageJobs);}
