 [Fact] public async Task NewerGenerationWinsAndOlderResultKeepsExistingCover(){await using var f=await Fixture.Create();await f.Entities.PatchAsync(f.Campaign.Id,new(){["cover_asset"]="previous.png"});var first=await f.Generation.StartAsync(f.Campaign.Id.ToString(),f.Gm.Id.ToString(),new("image","First idea",1,Guid.NewGuid().ToString()),default);var newest=await f.Generation.StartAsync(f.Campaign.Id.ToString(),f.Gm.Id.ToString(),new("image","New idea",1,Guid.NewGuid().ToString()),default);await f.Generation.RunAsync(first,default);Assert.False((await f.Store.RequireAsync(first.TypeSlug,first.Id.ToString())).Data.Flag("applied"));Assert.Equal("previous.png",(await f.Store.RequireAsync(f.Campaign.TypeSlug,f.Campaign.Id.ToString())).Data.Text("cover_asset"));await f.Generation.RunAsync(newest,default);Assert.True((await f.Store.RequireAsync(newest.TypeSlug,newest.Id.ToString())).Data.Flag("applied"));}
