 [Fact] public async Task StandardSettingsNeverExposeSecretsAndValidationOnlyDoesNotWrite(){await using var f=await Fixture.Create();var settings=new StorySettings(f.Store);var before=(await f.Store.ConfigAsync())!;var descriptor=await settings.DescribeAsync(f.Owner);Assert.DoesNotContain(before.Data.Text("proxy_secret"),descriptor.ToJsonString());var generation=descriptor["sections"]!.AsArray().Select(x=>x!.AsObject()).Single(x=>x.Text("id")=="generation");var fields=generation["fields"]!.AsArray().Select(x=>x!.AsObject()).ToDictionary(x=>x.Text("key"));Assert.Equal("entity_ref",fields["fast_quality_mode"].Text("type"));Assert.Equal("quality-tier",fields["fast_quality_mode"]["constraints"]!.AsObject().Text("target_type"));Assert.Equal("quality-tier",fields["quality_mode"]["constraints"]!.AsObject().Text("target_type"));Assert.Equal("comfyui-workflow",fields["workflow"]["constraints"]!.AsObject().Text("target_type"));var denied=await settings.DescribeAsync(f.Outsider.Id.ToString());Assert.Equal("extension_owner_required",denied.Text("error"));Assert.Empty(denied["sections"]!.AsArray());await settings.WriteAsync(f.Owner,"generation",new(){["visual_brief"]="Validated fixture",["fast_quality_mode"]="fast",["quality_mode"]="deep"},true);Assert.Equal(before.UpdatedAt,(await f.Store.ConfigAsync())!.UpdatedAt);await settings.WriteAsync(f.Owner,"generation",new(){["fast_quality_mode"]="fast",["quality_mode"]="deep"},false);Assert.Equal("fast",(await f.Store.ConfigAsync())!.Data.Text("fast_quality_mode"));Assert.Equal("deep",(await f.Store.ConfigAsync())!.Data.Text("quality_mode"));await Assert.ThrowsAsync<ArgumentException>(()=>settings.WriteAsync(f.Owner,"generation",new(){["quality_mode"]="missing"},false));await Assert.ThrowsAsync<ArgumentException>(()=>settings.WriteAsync(f.Owner,"access",new(){["public_url"]=42},false));}
