[Fact] public async Task PresenceDefaultsOnAndOnlyGmCanChangeItWithoutChangingMembership(){await using var f=await Fixture.Create();var member=await f.Campaigns.MembershipAsync(f.Campaign.Id.ToString(),f.Player.Id.ToString());var initial=(await f.Campaigns.PlayersAsync(f.Campaign.Id.ToString(),f.Gm.Id.ToString())).Select(StoryJson.Object).Single(p=>p.Text("id")==member.Id.ToString());Assert.True(initial.Flag("present"));await f.Campaigns.SetPresenceAsync(f.Campaign.Id.ToString(),f.Gm.Id.ToString(),member.Id.ToString(),new(false));var absent=(await f.Campaigns.PlayersAsync(f.Campaign.Id.ToString(),f.Gm.Id.ToString())).Select(StoryJson.Object).Single(p=>p.Text("id")==member.Id.ToString());Assert.False(absent.Flag("present"));Assert.True((await f.Campaigns.MembershipAsync(f.Campaign.Id.ToString(),f.Player.Id.ToString())).Data.Flag("active"));await Error("game_master_required",()=>f.Campaigns.SetPresenceAsync(f.Campaign.Id.ToString(),f.Player.Id.ToString(),member.Id.ToString(),new(true)));}
