 [Fact] public async Task StagedGenerationRepairsPublicationAfterCrashAndRequestContentIncludesRevision(){await using var f=await Fixture.Create();var request=new GenerationWrite("summary","",1,Guid.NewGuid().ToString());var failed=false;f.Entities.BeforeCas=(type,slug,data)=>{if(type=="storyboard-campaign"&&data.Text("latest_summary")!=""&&!failed){failed=true;throw new IOException("fixture crash before pointer");}};await Assert.ThrowsAsync<IOException>(()=>f.Generation.StartAsync(f.Campaign.Id.ToString(),f.Gm.Id.ToString(),request,default));var staged=Assert.Single(await f.Generation.ActiveAsync());Assert.Equal("staged",staged.Data.Text("state"));await f.Generation.RunAsync(staged,default);Assert.Empty(f.Compute.TextJobs);f.Entities.BeforeCas=null;using var restarted=f.NewGeneration();await restarted.RecoverAsync();var op=await restarted.StartAsync(f.Campaign.Id.ToString(),f.Gm.Id.ToString(),request,default);Assert.Equal(staged.Id,op.Id);Assert.Equal("pending",op.Data.Text("state"));await Error("operation_reused",()=>restarted.StartAsync(f.Campaign.Id.ToString(),f.Gm.Id.ToString(),request with{ExpectedRevision=2},default));await restarted.RunAsync(op,default);Assert.True((await f.Store.RequireAsync(op.TypeSlug,op.Id.ToString())).Data.Flag("applied"));}
