 [Fact] public async Task MusicIsCampaignScopedUsesFastAndDeepAndOnlyGmCuratesAndControlsPlayback(){await using var f=await Fixture.Create();using var client=await f.Host();var root="/campaigns/"+f.Campaign.Id+"/music";using(var outsider=await f.PublicRequest(root+"/playback",actor:f.Outsider))Assert.Equal(HttpStatusCode.Forbidden,(await client.SendAsync(outsider)).StatusCode);using(var player=await f.PublicRequest(root+"/playback","POST","{\"action\":\"pause\"}",f.Player))Assert.Equal(HttpStatusCode.Forbidden,(await client.SendAsync(player)).StatusCode);using(var list=await f.PublicRequest(root+"/playlists?offset=0&limit=28",actor:f.Player)){var response=await client.SendAsync(list);Assert.Equal(HttpStatusCode.OK,response.StatusCode);var page=await response.Content.ReadFromJsonAsync<JsonObject>();Assert.Equal(0,page!.Number("total"));}string trackId;using(var save=await f.PublicRequest(root+"/tracks","POST","{\"name\":\"Fixture track\",\"artist\":\"Fixture artist\",\"album\":\"Fixture album\",\"imageUrl\":null,\"durationMs\":180000,\"uri\":\"spotify:track:1234567890123456789012\"}",f.Gm)){var response=await client.SendAsync(save);Assert.Equal(HttpStatusCode.OK,response.StatusCode);trackId=(await response.Content.ReadFromJsonAsync<JsonObject>())!.Text("id");}string playlistId;using(var create=await f.PublicRequest(root+"/playlists","POST","{\"name\":\"Table score\",\"description\":\"Mixed sources\",\"operationId\":\""+Guid.NewGuid()+"\"}",f.Gm)){var response=await client.SendAsync(create);Assert.Equal(HttpStatusCode.OK,response.StatusCode);playlistId=(await response.Content.ReadFromJsonAsync<JsonObject>())!.Text("id");}using(var add=await f.PublicRequest(root+"/playlists/"+playlistId+"/tracks","POST","{\"trackId\":\""+trackId+"\"}",f.Gm)){var response=await client.SendAsync(add);Assert.Equal(HttpStatusCode.OK,response.StatusCode);Assert.Equal(1,(await response.Content.ReadFromJsonAsync<JsonObject>())!.Number("trackCount"));}using(var enqueue=await f.PublicRequest(root+"/queue","POST","{\"playlistId\":\""+playlistId+"\",\"operationId\":\""+Guid.NewGuid()+"\"}",f.Gm)){var response=await client.SendAsync(enqueue);Assert.Equal(HttpStatusCode.OK,response.StatusCode);Assert.Single((await response.Content.ReadFromJsonAsync<JsonArray>())!);}using(var find=await f.PublicRequest(root+"/find","POST","{\"situation\":\"A shadow moves below the water\"}",f.Gm))Assert.Equal(HttpStatusCode.OK,(await client.SendAsync(find)).StatusCode);Assert.Equal("fast",f.Compute.Requests.Single().QualityMode);f.Compute.TextJobs.Clear();f.Compute.TextJobs["storyboard-music-brief-"+StoryJson.Hash(f.Campaign.Id+":A shadow moves below the water")]=new AiCompletion("{\"title\":\"Drowned Crown\",\"prompt\":\"Submerged dread\",\"style\":\"dark ambient\",\"negativeTags\":\"vocals\",\"mood\":\"dread\",\"energy\":\"medium\",\"tempo\":\"slow\",\"instruments\":[\"low strings\"],\"narrativeArc\":\"rising\",\"durationSeconds\":150}","fixture");using(var brief=await f.PublicRequest(root+"/brief","POST","{\"situation\":\"A shadow moves below the water\"}",f.Gm))Assert.Equal(HttpStatusCode.OK,(await client.SendAsync(brief)).StatusCode);Assert.Equal("deep",f.Compute.Requests.Last().QualityMode);using(var providerQueue=await f.PublicRequest(root+"/playback","POST","{\"action\":\"queue\",\"uri\":\"spotify:track:1234567890123456789012\"}",f.Gm))Assert.Equal(HttpStatusCode.OK,(await client.SendAsync(providerQueue)).StatusCode);Assert.Contains("queue:spotify:track:1234567890123456789012",f.Music.Commands);}
