 [Fact] public async Task VisualsGenerateCurateQueueAndProjectWithIdempotentRevisionedCommands(){await using var f=await Fixture.Create();using var client=await f.Host();var root="/campaigns/"+f.Campaign.Id+"/visuals";var situation="The drowned throne room wakes";using(var denied=await f.PublicRequest(root+"/match","POST","{\"situation\":\""+situation+"\"}",f.Player))Assert.Equal(HttpStatusCode.Forbidden,(await client.SendAsync(denied)).StatusCode);f.Compute.TextJobs["storyboard-visual-match-"+StoryJson.Hash(f.Campaign.Id+":"+situation)]=new AiCompletion("{\"title\":\"Drowned throne\",\"prompt\":\"Moonlit submerged throne room\",\"mood\":\"dread\",\"tags\":[\"water\",\"moonlight\"]}","fixture");using(var match=await f.PublicRequest(root+"/match","POST","{\"situation\":\""+situation+"\"}",f.Gm))Assert.Equal(HttpStatusCode.OK,(await client.SendAsync(match)).StatusCode);Assert.Equal("fast",f.Compute.Requests.Last().QualityMode);f.Compute.TextJobs["storyboard-visual-brief-"+StoryJson.Hash(f.Campaign.Id+":"+situation)]=new AiCompletion("{\"title\":\"Drowned court\",\"transition\":\"crossfade\",\"intervalSeconds\":20,\"frames\":[{\"title\":\"Still water\",\"prompt\":\"A drowned throne under cold moonlight\",\"mood\":\"unease\",\"tags\":[\"water\"]},{\"title\":\"Rising shadow\",\"prompt\":\"A vast shadow moving beneath the throne\",\"mood\":\"dread\",\"tags\":[\"shadow\"]}]}","fixture");JsonObject brief;using(var request=await f.PublicRequest(root+"/brief","POST","{\"situation\":\""+situation+"\"}",f.Gm)){var response=await client.SendAsync(request);Assert.Equal(HttpStatusCode.OK,response.StatusCode);brief=(await response.Content.ReadFromJsonAsync<JsonObject>())!;}Assert.Equal("deep",f.Compute.Requests.Last().QualityMode);var operation=Guid.NewGuid();var generationBody=new JsonObject{{"operationId",operation.ToString()},{"situation",situation},{"brief",brief.DeepClone()},{"confirmed",true}}.ToJsonString();string generationId;using(var start=await f.PublicRequest(root+"/generations","POST",generationBody,f.Gm)){var response=await client.SendAsync(start);Assert.Equal(HttpStatusCode.OK,response.StatusCode);generationId=(await response.Content.ReadFromJsonAsync<JsonObject>())!.Text("id");}var generation=await f.Store.RequireAsync("storyboard-visual-generation",generationId);await f.Visuals.RunGenerationAsync(generation,default);await f.Visuals.RunGenerationAsync(generation,default);Assert.Equal(2,f.Compute.ImageJobs.Count(p=>p.Key.StartsWith("storyboard-visual-")));Assert.Equal(2,f.Compute.Uploads);JsonObject completed;using(var status=await f.PublicRequest(root+"/generations/"+generationId,actor:f.Gm)){var response=await client.SendAsync(status);Assert.Equal(HttpStatusCode.OK,response.StatusCode);completed=(await response.Content.ReadFromJsonAsync<JsonObject>())!;}Assert.Equal("completed",completed.Text("state"));Assert.Equal(2,completed["candidates"]!.AsArray().Count);var candidate=completed["candidates"]!.AsArray()[0]!.AsObject().Text("id");string visual;using(var promote=await f.PublicRequest(root+"/candidates/"+candidate+"/promote","POST","{}",f.Gm)){var response=await client.SendAsync(promote);Assert.Equal(HttpStatusCode.OK,response.StatusCode);visual=(await response.Content.ReadFromJsonAsync<JsonObject>())!.Text("id");}using(var media=await f.PublicRequest(root+"/images/"+visual,actor:f.Player))Assert.Equal(HttpStatusCode.OK,(await client.SendAsync(media)).StatusCode);string set;using(var create=await f.PublicRequest(root+"/sets","POST",new JsonObject{{"name","Opening visions"},{"description",""},{"operationId",Guid.NewGuid().ToString()}}.ToJsonString(),f.Gm)){var response=await client.SendAsync(create);Assert.Equal(HttpStatusCode.OK,response.StatusCode);set=(await response.Content.ReadFromJsonAsync<JsonObject>())!.Text("id");}using(var add=await f.PublicRequest(root+"/sets/"+set+"/items","POST",new JsonObject{{"visualId",visual}}.ToJsonString(),f.Gm))Assert.Equal(HttpStatusCode.OK,(await client.SendAsync(add)).StatusCode);using(var enqueue=await f.PublicRequest(root+"/queue","POST",new JsonObject{{"setId",set},{"operationId",Guid.NewGuid().ToString()}}.ToJsonString(),f.Gm)){var response=await client.SendAsync(enqueue);Assert.Equal(HttpStatusCode.OK,response.StatusCode);Assert.Single((await response.Content.ReadFromJsonAsync<JsonArray>())!);}var commandId=Guid.NewGuid();var command=new JsonObject{{"action","play"},{"operationId",commandId.ToString()},{"expectedRevision",0}}.ToJsonString();using(var play=await f.PublicRequest(root+"/session/commands","POST",command,f.Gm)){var response=await client.SendAsync(play);Assert.Equal(HttpStatusCode.OK,response.StatusCode);Assert.True((await response.Content.ReadFromJsonAsync<JsonObject>())!.Flag("playing"));}using(var retry=await f.PublicRequest(root+"/session/commands","POST",command,f.Gm))Assert.Equal(HttpStatusCode.OK,(await client.SendAsync(retry)).StatusCode);using(var stale=await f.PublicRequest(root+"/session/commands","POST",new JsonObject{{"action","pause"},{"operationId",Guid.NewGuid().ToString()},{"expectedRevision",0}}.ToJsonString(),f.Gm)){var response=await client.SendAsync(stale);Assert.Equal(HttpStatusCode.Conflict,response.StatusCode);Assert.Equal("visual_session_changed",(await response.Content.ReadFromJsonAsync<JsonObject>())!.Text("error"));}}
 [Fact] public async Task ConfirmedMusicGenerationIsIdempotentIngestsCandidatesPromotesAndSupportsRanges(){await using var f=await Fixture.Create();using var client=await f.Host();var root="/campaigns/"+f.Campaign.Id+"/music";f.Compute.MusicResultJson="{\"operation\":\"generate\",\"providerTaskId\":\"task-1\",\"credits\":{\"consumed\":12},\"artifacts\":[{\"name\":\"audio-0\",\"contentType\":\"audio/mpeg\"},{\"name\":\"cover-0\",\"contentType\":\"image/png\"}],\"tracks\":[{\"title\":\"Drowned Crown A\",\"providerAudioId\":\"audio-1\",\"durationSeconds\":150,\"audioArtifact\":\"audio-0\",\"coverArtifact\":\"cover-0\"}]}";var operation=Guid.NewGuid();var json="{\"operationId\":\""+operation+"\",\"situation\":\"Flooded throne room\",\"confirmed\":true,\"brief\":{\"title\":\"Drowned Crown\",\"prompt\":\"Submerged dread\",\"style\":\"dark ambient\",\"negativeTags\":\"vocals\",\"mood\":\"dread\",\"energy\":\"medium\",\"tempo\":\"slow\",\"instruments\":[\"low strings\"],\"narrativeArc\":\"rising\",\"durationSeconds\":150,\"instrumental\":true}}";string id;using(var start=await f.PublicRequest(root+"/generations","POST",json,f.Gm)){var response=await client.SendAsync(start);Assert.Equal(HttpStatusCode.OK,response.StatusCode);id=(await response.Content.ReadFromJsonAsync<JsonObject>())!.Text("id");}var service=f.App!.Services.GetRequiredService<StoryMusic>();var entity=await f.Store.RequireAsync("storyboard-music-generation",id);await service.RunGenerationAsync(entity,default);await service.RunGenerationAsync(entity,default);Assert.Single(f.Compute.ImageJobs.Where(p=>p.Key.StartsWith("storyboard-music-")));Assert.Equal(2,f.Compute.Uploads);JsonObject done;using(var status=await f.PublicRequest(root+"/generations/"+id,actor:f.Gm)){var response=await client.SendAsync(status);Assert.Equal(HttpStatusCode.OK,response.StatusCode);done=(await response.Content.ReadFromJsonAsync<JsonObject>())!;}Assert.Equal("completed",done.Text("state"));Assert.Equal(12,done.Number("creditsConsumed"));var candidate=done["candidates"]!.AsArray()[0]!.AsObject().Text("id");using(var promote=await f.PublicRequest(root+"/candidates/"+candidate+"/promote","POST","{}",f.Gm)){var response=await client.SendAsync(promote);Assert.Equal(HttpStatusCode.OK,response.StatusCode);Assert.Equal("generated",(await response.Content.ReadFromJsonAsync<JsonObject>())!.Text("sourceKind"));}using(var media=await f.PublicRequest(root+"/candidates/"+candidate+"/audio",actor:f.Player)){media.Headers.Range=new System.Net.Http.Headers.RangeHeaderValue(0,1);var response=await client.SendAsync(media);Assert.Equal(HttpStatusCode.PartialContent,response.StatusCode);Assert.Equal(2,(await response.Content.ReadAsByteArrayAsync()).Length);}}
 [Fact] public async Task StaleGenerationRetainsCoverAndCasRetryCannotLeaveAppliedTrue(){await using var f=await Fixture.Create();await f.Entities.PatchAsync(f.Campaign.Id,new(){["cover_asset"]="previous-cover.png"});var op=await f.Generation.StartAsync(f.Campaign.Id.ToString(),f.Gm.Id.ToString(),new("image","Landscape",1,Guid.NewGuid().ToString()),default);var injected=false;f.Entities.BeforeCas=(type,slug,data)=>{if(type=="storyboard-campaign"&&data.Text("applied_operation")==op.Id.ToString()&&!injected){injected=true;f.Entities.BeforeCas=null;f.Entities.PatchAsync(f.Campaign.Id,new(){["revision"]=2}).GetAwaiter().GetResult();}};await f.Generation.RunAsync(op,default);var completed=await f.Store.RequireAsync(op.TypeSlug,op.Id.ToString());Assert.Equal("completed",completed.Data.Text("state"));Assert.False(completed.Data.Flag("applied"));Assert.Equal("previous-cover.png",(await f.Store.RequireAsync(f.Campaign.TypeSlug,f.Campaign.Id.ToString())).Data.Text("cover_asset"));}
