 [Fact] public async Task WorkspaceIsGmScopedSchemaDrivenAndRevisionSafe(){await using var f=await Fixture.Create();var campaign=await f.Store.RequireAsync("storyboard-campaign",f.Campaign.Id.ToString());var root=(await f.Entities.GetAsync(StoryJson.Id(campaign.Data.Text("workspace"))))!;await f.Entities.UpsertBySlugAsync("entity-type","fixture-place","Place",new(){["scope"]=root.Slug,["description"]="Campaign locations",["icon"]="ph-bold ph-map-pin"});await f.Entities.UpsertBySlugAsync("field-definition","fixture-place--description","Description",new(){["parent_type"]="fixture-place",["field_type"]="markdown",["sort_order"]=1,["is_required"]=true});await f.Entities.UpsertBySlugAsync("field-definition","fixture-place--api-token","API token",new(){["parent_type"]="fixture-place",["field_type"]="secret",["sort_order"]=2,["is_required"]=false});var place=await f.Entities.UpsertBySlugAsync("fixture-place","glass-observatory","Glass Observatory",new(){["parent"]=root.Slug,["description"]="Old notes",["api_token"]="never-return-this"});await f.Entities.UpsertBySlugAsync("fixture-place","foreign-place","Foreign",new(){["parent"]=Guid.NewGuid().ToString(),["description"]="Outside"});using var client=await f.Host();using(var denied=await f.PublicRequest("/campaigns/"+f.Campaign.Id+"/workspace",actor:f.Player))Assert.Equal(HttpStatusCode.Forbidden,(await client.SendAsync(denied)).StatusCode);JsonObject snapshot;using(var request=await f.PublicRequest("/campaigns/"+f.Campaign.Id+"/workspace",actor:f.Gm)){var response=await client.SendAsync(request);Assert.Equal(HttpStatusCode.OK,response.StatusCode);snapshot=(await response.Content.ReadFromJsonAsync<JsonObject>())!;}var entities=snapshot["entities"]!.AsArray();var projected=entities.Select(x=>x!.AsObject()).Single(x=>x.Text("id")==place.Id.ToString());Assert.Equal("Old notes",projected["data"]!.AsObject().Text("description"));Assert.Null(projected["data"]!["api_token"]);Assert.DoesNotContain(entities,x=>x!.AsObject().Text("name")=="Foreign");var body=new JsonObject{{"name","Renamed Observatory"},{"expectedUpdatedAt",place.UpdatedAt.ToString("O")},{"data",new JsonObject{{"description","New notes"},{"api_token","stolen"}}}}.ToJsonString();using(var save=await f.PublicRequest("/campaigns/"+f.Campaign.Id+"/workspace/entities/"+place.Id,"PUT",body,f.Gm)){var response=await client.SendAsync(save);Assert.Equal(HttpStatusCode.OK,response.StatusCode);}var stored=(await f.Entities.GetAsync(place.Id))!;Assert.Equal("Renamed Observatory",stored.Name);Assert.Equal("New notes",stored.Data.Text("description"));Assert.Equal("never-return-this",stored.Data.Text("api_token"));using(var stale=await f.PublicRequest("/campaigns/"+f.Campaign.Id+"/workspace/entities/"+place.Id,"PUT",body,f.Gm)){var response=await client.SendAsync(stale);Assert.Equal(HttpStatusCode.Conflict,response.StatusCode);Assert.Equal("workspace_entity_changed",(await response.Content.ReadFromJsonAsync<JsonObject>())!.Text("error"));}}
